import {portraits,statements,chats} from '../content.js';import {gameFrame,escapeHTML} from '../ui.js';import {shape} from '../ui.js';
function preferenceArt(trait){const marks={Planning:['square','square','square'],Exploration:['triangle','star','circle'],'Independent focus':['circle'],Collaboration:['circle','circle','circle'],Consistency:['square','square'],Adaptability:['arrow','arrow'],Reflection:['diamond']};return `<div class="preference-art" aria-hidden="true">${(marks[trait]||['circle']).map((s,i)=>shape(s,i%2?'#84a4d5':'#416fb0',35,i*35)).join('')}</div>`;}
export function mountPreferences(root,c,kind){const list=kind==='portrait'?portraits:kind==='portraitxt'?statements:chats;let index=0;const responses=[];c.metrics.responses=responses;function next(){if(index>=list.length){c.complete();return;}c.setRound(index+1,list.length);const q=list[index];const area=gameFrame(root,kind==='teamchat'?'A conversation at work':kind==='portraitxt'?'How much do you agree?':q.prompt,'Choose what feels most like you. There are no right or wrong answers.');if(kind==='teamchat')area.innerHTML=`<div class="chat-thread"><div class="chat-person"><span>${q.from[0]}</span>${q.from} <small>Teammate</small></div><div class="chat-bubble">${q.prompt}</div></div>`;else if(kind==='portraitxt')area.innerHTML=`<p class="statement">“${q.text}”</p>`;else area.innerHTML='';const options=kind==='portraitxt'?['Strongly disagree','Disagree','Neither agree nor disagree','Agree','Strongly agree'].map((text,i)=>({text,trait:q.trait,value:i+1})):q.options;const box=document.createElement('div');box.className=kind==='portrait'?'portrait-choices':'preference-choices';options.forEach((option,i)=>{const b=document.createElement('button');b.className='preference-option';b.innerHTML=(kind==='portrait'?preferenceArt(option.trait):'')+`<span>${escapeHTML(option.text)}</span>`;b.onclick=()=>{if(!c.session.answer(index,false))return;responses.push({prompt:q.prompt||q.text,choice:option.text,trait:option.trait,...(option.value?{value:option.value}:{})});box.querySelectorAll('button').forEach(x=>x.disabled=true);b.classList.add('chosen');c.updateScore();index++;c.session.schedule(next,250);};box.append(b);});area.append(box);area.insertAdjacentHTML('beforeend',`<p class="subtle">${index+1} of ${list.length} prompts · Practice reflection only</p>`);}next();return {dispose(){}};}
